    acting_organisation_id BIGINT UNSIGNED NULL,
    actor_user_id BIGINT UNSIGNED NULL,
    actor_member_id BIGINT UNSIGNED NULL,
    project_id BIGINT UNSIGNED NULL,
    action_key VARCHAR(160) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    subject_type VARCHAR(120) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    subject_public_id VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NULL,
    correlation_id VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NULL,
    change_summary JSON NULL,
    event_metadata JSON NULL,

    PRIMARY KEY (id),
    UNIQUE KEY uq_audit_events_public_id (event_public_id),
    KEY idx_audit_events_organisation_time (acting_organisation_id, occurred_at, id),
    KEY idx_audit_events_project_time (project_id, occurred_at, id),
    KEY idx_audit_events_actor_time (actor_user_id, occurred_at, id),
    KEY idx_audit_events_subject (subject_type, subject_public_id, occurred_at),
    KEY idx_audit_events_correlation (correlation_id),

    CONSTRAINT fk_audit_events_organisation
        FOREIGN KEY (acting_organisation_id)
        REFERENCES organisations (id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
    CONSTRAINT fk_audit_events_actor_user
        FOREIGN KEY (actor_user_id)
        REFERENCES users (id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
    CONSTRAINT fk_audit_events_actor_member
        FOREIGN KEY (actor_member_id)
        REFERENCES organisation_members (id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
    CONSTRAINT fk_audit_events_project
        FOREIGN KEY (project_id)
        REFERENCES projects (id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT
) ENGINE=InnoDB
  DEFAULT CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

-- -----------------------------------------------------------------------------
-- Required application invariants not completely expressible as simple FKs
-- -----------------------------------------------------------------------------
--
-- The application/domain layer MUST enforce and test the following:
--
-- 1. The owning organisation is inserted into project_organisations when a project
--    is created.
-- 2. invited_by_member_id in project_organisations must have authority in the
--    owning organisation/project context.
-- 3. Audit actor_member_id, when present, must correspond to actor_user_id and the
--    acting organisation context.
-- 4. At least one verified/usable identity method must exist before an account can
--    authenticate; exact rule depends on the authentication ADR.
-- 5. An active organisation should have a primary business location only if the
--    product workflow requires one; this is not a universal relational invariant.
-- 6. Effective permissions are resolved by policy. Recommended precedence:
--       explicit deny > explicit allow > role grant > default deny
--    followed by project/record-level scope checks.
--
-- These invariants require automated integration tests in addition to DDL constraints.
-- ===== END database/schema/001-platform-kernel.sql =====

-- ===== BEGIN database/schema/002-crm-parties.sql =====
-- NuBlox: Digital Applications
-- Schema package 002: CRM and Party Model
-- Depends on: 001-platform-kernel.sql
-- Target: MySQL 8.4 / InnoDB
-- Design target: 3NF by default
-- Generated: 2026-08-15
--
-- PRINCIPLES:
-- 1. CRM parties are private to the owning NuBlox organisation/tenant.
-- 2. A party can hold many business roles; do not duplicate client/supplier/etc identity.
-- 3. A person/organisation contact relationship owns job title and department.
-- 4. Subtype exclusivity (person vs organisation) is a cross-table domain invariant and
--    must be enforced by application services and integration tests.

SET NAMES utf8mb4;
SET time_zone = '+00:00';

