        ON DELETE RESTRICT,
    CONSTRAINT fk_quotation_responses_party
        FOREIGN KEY (responding_party_id, organisation_id)
        REFERENCES parties (id, organisation_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
