) ENGINE=InnoDB
  DEFAULT CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

CREATE TABLE contract_version_key_dates (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
