-- -----------------------------------------------------------------------------
-- Required application invariants not completely expressible as simple FKs
-- -----------------------------------------------------------------------------
-- 1. Cross-project references are prohibited even where individual FKs are otherwise valid.
-- 2. A participant organisation must have effective project permission before creating,
--    viewing, issuing, reviewing or approving a record; FK participation alone is insufficient.
-- 3. Once issued/locked, information-container versions and authoritative file metadata are
--    immutable through normal write APIs. Corrections create a new version.
-- 4. Supersession relationships must remain within the same logical information container
--    and must not contain cycles.
-- 5. information_version_issue_events must reference a version belonging to the stated project.
-- 6. Transmittal items must belong to the transmittal project and be visible to the issuer.
-- 7. RFI responses must come from an authorised addressee/project participant according to
--    configured workflow; an FK-valid participant is not automatically an authorised responder.
-- 8. RFI close/reopen transitions require configured state-machine rules and audit events.
-- 9. Submitted submittals cannot have their submitted item set rewritten; revised material
--    requires a new submittal/revision according to workflow policy.
-- 10. Formal instructions become immutable once issued; corrections use supersession/withdrawal.
-- 11. Project change events are information-management facts. Package 009 commercial variation
--    logic may reference them but must not overwrite them.
-- 12. Review workflow step ordering, completion and decision-rule evaluation are transactionally
--    enforced in domain services and integration tests.
-- 13. Null reviewer_member_id means an organisation-level reviewer assignment. The application
--    must ensure only one organisation-level assignment exists per step/org where MySQL NULL
--    uniqueness semantics would otherwise permit duplicates.
-- 14. Object uploads are quarantined until malware/security checks pass; issued authoritative
--    versions may not reference quarantined/failed objects.
-- 15. Hard deletion of issued/transmitted/reviewed contractual information is prohibited through
--    ordinary business APIs. Retention, withdrawal, void and supersession preserve evidence.
-- ===== END database/schema/007-project-information-documents.sql =====

-- ===== BEGIN database/schema/007-project-information-integrity.sql =====
-- NuBlox: Digital Applications
-- Schema package 007: Project Information integrity hardening
-- Depends on: 007-project-information-documents.sql
-- Target: MySQL 8.4 / InnoDB
-- Generated: 2026-08-15
--
-- Pre-development companion integrity stage. Consolidate further into Package 007
-- when the production migration baseline is frozen.

SET NAMES utf8mb4;
SET time_zone = '+00:00';

-- -----------------------------------------------------------------------------
-- 1. Project sites are shared project context, not owned document context.
--    Any valid project participant's information container may reference a site.
-- -----------------------------------------------------------------------------

ALTER TABLE project_sites
    ADD UNIQUE KEY uq_project_sites_id_project (id, project_id);

-- MySQL 8.4 requires the old named FK to be dropped before a constraint using the
-- same name is added; do not combine these two operations in one ALTER statement.
ALTER TABLE information_containers
    DROP FOREIGN KEY fk_information_containers_site;

ALTER TABLE information_containers
    ADD CONSTRAINT fk_information_containers_site
        FOREIGN KEY (project_site_id, project_id)
        REFERENCES project_sites (id, project_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT;

-- -----------------------------------------------------------------------------
-- 2. Review-assignment identity and 3NF decision linkage are now consolidated
--    into 007-project-information-documents.sql so the base package is valid
--    before this integrity stage is applied.
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- 3. External transmittal recipients use the issuing tenant's private Party record.
--    Do not allow a transmittal to reference another tenant's CRM party namespace.
-- -----------------------------------------------------------------------------

ALTER TABLE transmittal_recipients
    DROP FOREIGN KEY fk_transmittal_recipients_party,
    DROP CHECK ck_transmittal_recipients_source,
    DROP COLUMN source_party_owner_organisation_id;

ALTER TABLE transmittal_recipients
    ADD CONSTRAINT fk_transmittal_recipients_party
        FOREIGN KEY (source_party_id, issuing_organisation_id)
        REFERENCES parties (id, organisation_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
    ADD CONSTRAINT ck_transmittal_recipients_source
        CHECK (
            (recipient_project_organisation_id IS NOT NULL AND source_party_id IS NULL)
            OR
            (recipient_project_organisation_id IS NULL AND source_party_id IS NOT NULL)
            OR
            (recipient_project_organisation_id IS NULL AND source_party_id IS NULL)
        );

-- Required application invariant retained:
-- information_review_step_reviewers.project_id must match the project of its workflow.
-- This is intentionally tested in the domain/integration layer in addition to the
-- project_organisations FK used for reviewer participation.
-- ===== END database/schema/007-project-information-integrity.sql =====

-- ===== BEGIN database/schema/008-site-quality-safety.sql =====
-- NuBlox: Digital Applications
-- Schema package 008: Site Operations, Quality and Safety
-- Depends on: 001-platform-kernel.sql, 002-crm-parties.sql,
--             003-sales-quotes.sql, 006-workforce-time-scheduling.sql,
--             007-project-information-documents.sql,
--             007-project-information-integrity.sql
-- Target: MySQL 8.4 / InnoDB
-- Design target: 3NF by default
-- Generated: 2026-08-15
--
-- PRINCIPLES:
-- 1. Site diary, quality and safety evidence are independent auditable facts.
-- 2. Projects, project sites, workers, CRM parties and controlled information are reused.
-- 3. Inspection definitions are versioned; published definitions are historical facts.
-- 4. Defects and NCRs have separate lifecycles even when related.
-- 5. RAMS approval and briefing evidence targets exact controlled-information revisions.
-- 6. Safety events use a supertype/subtype model to avoid duplicated nullable columns.
-- 7. Historical plant/visitor/delivery snapshots are evidence, not competing master data.

SET NAMES utf8mb4;
SET time_zone = '+00:00';

-- -----------------------------------------------------------------------------
-- Global controlled reference data
-- -----------------------------------------------------------------------------

CREATE TABLE quality_inspection_item_types (
    id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    code VARCHAR(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    name VARCHAR(120) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    PRIMARY KEY (id),
    UNIQUE KEY uq_quality_inspection_item_types_code (code)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;

CREATE TABLE quality_finding_types (
    id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    code VARCHAR(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    name VARCHAR(120) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    PRIMARY KEY (id),
    UNIQUE KEY uq_quality_finding_types_code (code)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;

CREATE TABLE permit_types (
    id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    name VARCHAR(160) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    PRIMARY KEY (id),
    UNIQUE KEY uq_permit_types_code (code)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;

CREATE TABLE safety_briefing_types (
    id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    name VARCHAR(160) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    PRIMARY KEY (id),
    UNIQUE KEY uq_safety_briefing_types_code (code)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;

-- -----------------------------------------------------------------------------
-- Site diaries
-- -----------------------------------------------------------------------------

CREATE TABLE site_diaries (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    project_id BIGINT UNSIGNED NOT NULL,
    owning_organisation_id BIGINT UNSIGNED NOT NULL,
    project_site_id BIGINT UNSIGNED NOT NULL,
    public_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    diary_date DATE NOT NULL,
    shift_label VARCHAR(80) NULL,
    status VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'draft',
    summary TEXT NULL,
    created_by_member_id BIGINT UNSIGNED NOT NULL,
    submitted_by_member_id BIGINT UNSIGNED NULL,
    submitted_at DATETIME(6) NULL,
    approved_by_member_id BIGINT UNSIGNED NULL,
    approved_at DATETIME(6) NULL,
    locked_at DATETIME(6) NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_site_diaries_public_id (public_id),
    UNIQUE KEY uq_site_diaries_id_owner (id, owning_organisation_id),
    UNIQUE KEY uq_site_diaries_day (
        project_id, owning_organisation_id, project_site_id, diary_date
    ),
    KEY idx_site_diaries_project_date (project_id, diary_date, status),
    CONSTRAINT fk_site_diaries_participant
        FOREIGN KEY (project_id, owning_organisation_id)
        REFERENCES project_organisations (project_id, participant_organisation_id)
        ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT fk_site_diaries_site
        FOREIGN KEY (project_site_id, project_id)
        REFERENCES project_sites (id, project_id)
        ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT fk_site_diaries_creator
        FOREIGN KEY (created_by_member_id, owning_organisation_id)
        REFERENCES organisation_members (id, organisation_id)
        ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT fk_site_diaries_submitter
        FOREIGN KEY (submitted_by_member_id, owning_organisation_id)
        REFERENCES organisation_members (id, organisation_id)
        ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT fk_site_diaries_approver
        FOREIGN KEY (approved_by_member_id, owning_organisation_id)
        REFERENCES organisation_members (id, organisation_id)
        ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT ck_site_diaries_status
        CHECK (status IN ('draft', 'submitted', 'approved', 'locked', 'cancelled')),
    CONSTRAINT ck_site_diaries_submit
        CHECK (
            (submitted_at IS NULL AND submitted_by_member_id IS NULL)
            OR (submitted_at IS NOT NULL AND submitted_by_member_id IS NOT NULL)
        ),
    CONSTRAINT ck_site_diaries_approve
        CHECK (
            (approved_at IS NULL AND approved_by_member_id IS NULL)
            OR (approved_at IS NOT NULL AND approved_by_member_id IS NOT NULL)
        ),
    CONSTRAINT ck_site_diaries_lock
        CHECK (locked_at IS NULL OR status = 'locked')
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;

CREATE TABLE site_diary_weather_records (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    site_diary_id BIGINT UNSIGNED NOT NULL,
    owning_organisation_id BIGINT UNSIGNED NOT NULL,
    observed_at DATETIME(6) NOT NULL,
    condition_code VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    temperature_c DECIMAL(5,2) NULL,
    wind_speed_mps DECIMAL(8,3) NULL,
    rainfall_mm DECIMAL(10,3) NULL,
    impact_note VARCHAR(1000) NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_site_diary_weather_observation (
        site_diary_id, observed_at
    ),
    CONSTRAINT fk_site_diary_weather_diary
        FOREIGN KEY (site_diary_id, owning_organisation_id)
        REFERENCES site_diaries (id, owning_organisation_id)
        ON UPDATE RESTRICT ON DELETE CASCADE,
    CONSTRAINT ck_site_diary_weather_condition
        CHECK (condition_code IN (
            'clear', 'cloudy', 'rain', 'heavy_rain', 'snow', 'ice',
            'fog', 'wind', 'storm', 'hot', 'cold', 'mixed', 'other'
        )),
    CONSTRAINT ck_site_diary_weather_wind CHECK (wind_speed_mps IS NULL OR wind_speed_mps >= 0),
    CONSTRAINT ck_site_diary_weather_rain CHECK (rainfall_mm IS NULL OR rainfall_mm >= 0)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;

CREATE TABLE site_diary_worker_entries (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
