-- -----------------------------------------------------------------------------
-- Handover packages
-- -----------------------------------------------------------------------------

CREATE TABLE handover_packages (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    organisation_id BIGINT UNSIGNED NOT NULL,
    facility_id BIGINT UNSIGNED NOT NULL,
